import { useEffect, useState, type ReactNode } from 'react'
import { Link, useNavigate, useParams } from 'react-router-dom'
import { ArrowLeft, LockKeyhole, Plus, RefreshCw, Save, Trash2, Play, Trophy, PowerOff } from 'lucide-react'
import { PageHeader } from '../../components/layout/PageHeader'
import { StatusBadge } from '../../components/status/StatusBadge'
import { Button } from '../../lib/shadcn/button'
import { toast } from '../../lib/shadcn/sonner'
import { supabase } from '../../lib/supabase'

const input='h-9 w-full rounded-md border border-border bg-background px-2.5 text-sm outline-none focus:ring-1 focus:ring-ring'
const area='min-h-24 w-full rounded-md border border-border bg-background px-2.5 py-2 text-sm outline-none focus:ring-1 focus:ring-ring'
const errorText=(e:unknown)=>{const x=e as any;if(x?.message)return [x.message,x.code?`(${x.code})`:'',x.details||'',x.hint?`Hint: ${x.hint}`:''].filter(Boolean).join(' ');return typeof e==='string'?e:'Operation failed'}
const toIso=(v?:string)=>v?new Date(v).toISOString():null
const fromIso=(v?:string|null)=>v?new Date(v).toISOString().slice(0,16):''
const dateText=(v?:string|null)=>v?new Date(v).toLocaleString():'—'

function Card({title,children,actions}:{title:string;children:ReactNode;actions?:ReactNode}){return <section className="rounded-lg border border-border bg-card p-density-lg shadow-retool-sm"><div className="mb-density-md flex items-center justify-between gap-3"><h2 className="text-base font-semibold">{title}</h2>{actions}</div>{children}</section>}
function Field({label,children,required=false}:{label:string;children:ReactNode;required?:boolean}){return <label className="flex flex-col gap-1.5 text-xs font-medium text-muted-foreground"><span>{label}{required?' *':''}</span>{children}</label>}
function Text({label,value,onChange,type='text',required=false}:{label:string;value:any;onChange:(v:string)=>void;type?:string;required?:boolean}){return <Field label={label} required={required}><input className={input} type={type} required={required} value={value??''} onChange={e=>onChange(e.target.value)}/></Field>}
function Area({label,value,onChange}:{label:string;value:any;onChange:(v:string)=>void}){return <Field label={label}><textarea className={area} value={value??''} onChange={e=>onChange(e.target.value)}/></Field>}
function Select({label,value,onChange,options}:{label:string;value:any;onChange:(v:string)=>void;options:{value:string;label:string}[]}){return <Field label={label}><select className={input} value={value??''} onChange={e=>onChange(e.target.value)}>{options.map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select></Field>}
function Toggle({label,checked,onChange}:{label:string;checked:boolean;onChange:(v:boolean)=>void}){return <label className="flex items-center gap-2 text-sm"><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)}/><span>{label}</span></label>}
function Back({to,title}:{to:string;title:string}){return <PageHeader title={title} actions={<Button asChild variant="outline"><Link to={to}><ArrowLeft className="h-4 w-4"/>Back</Link></Button>}/>}
function Actions({to}:{to:string}){return <div className="flex justify-end gap-2"><Button asChild type="button" variant="outline"><Link to={to}>Cancel</Link></Button><Button type="submit"><Save className="h-4 w-4"/>Save</Button></div>}
function Empty({children}:{children:ReactNode}){return <div className="py-8 text-center text-sm text-muted-foreground">{children}</div>}

export function BonusesPage(){
 const [rows,setRows]=useState<any[]>([]);const [loading,setLoading]=useState(true)
 const load=async()=>{setLoading(true);try{const {data,error}=await supabase.from('bonuses').select('id,partner_id,title,brand_name,bonus_type,delivery_type,bonus_access_type,status,featured,starts_at,expires_at,updated_at,partners(name)').order('sort_order').order('created_at',{ascending:false});if(error)throw error;setRows(data??[])}catch(e){toast.error(errorText(e))}finally{setLoading(false)}}
 useEffect(()=>{void load()},[])
 async function remove(id:string){if(!window.confirm('Delete this bonus?'))return;try{const refs=await Promise.all([supabase.from('challenge_prizes').select('id',{count:'exact',head:true}).eq('bonus_id',id),supabase.from('challenge_prize_codes').select('id',{count:'exact',head:true}).eq('bonus_id',id),supabase.from('user_bonus_grants').select('id',{count:'exact',head:true}).eq('bonus_id',id)]);const bad=refs.find(x=>x.error);if(bad?.error)throw bad.error;if(refs.some(x=>Number(x.count??0)>0))throw new Error('This bonus has prize/grant history. Archive it instead of deleting it.');const {error}=await supabase.from('bonuses').delete().eq('id',id);if(error)throw error;toast.success('Bonus deleted');await load()}catch(e){toast.error(errorText(e))}}
 async function toggle(r:any){const next=r.status==='active'?'paused':'active';try{const {error}=await supabase.rpc('admin_set_bonus_status',{p_bonus_id:r.id,p_status:next});if(error)throw error;toast.success(`Bonus ${next}`);await load()}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Bonuses" description="Manage the public bonuses catalog." actions={<><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button asChild><Link to="/bonuses/new"><Plus className="h-4 w-4"/>Create bonus</Link></Button></>}/><Card title={`Bonuses (${rows.length})`}><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Offer</th><th>Type</th><th>Delivery</th><th>Access</th><th>Status</th><th>Partner</th><th>Updated</th><th/></tr></thead><tbody>{rows.map(r=><tr key={r.id} className="border-b border-border/70"><td className="py-2"><div className="font-medium">{r.title}</div><div className="text-xs text-muted-foreground">{r.brand_name} · {r.slug??''}</div></td><td>{r.bonus_type}</td><td>{r.delivery_type}</td><td>{r.bonus_access_type}</td><td><StatusBadge status={r.status} dense/></td><td>{r.partners?.name??'—'}</td><td>{dateText(r.updated_at)}</td><td className="text-right whitespace-nowrap"><Button asChild size="sm" variant="ghost"><Link to={`/bonuses/${r.id}/edit`}>Edit</Link></Button><Button size="sm" variant="ghost" onClick={()=>void toggle(r)}>{r.status==='active'?'Pause':'Activate'}</Button><Button size="sm" variant="ghost" onClick={()=>void remove(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></td></tr>)}</tbody></table>{!rows.length&&<Empty>{loading?'Loading…':'No bonuses yet.'}</Empty>}</div></Card></div>
}

const bonusDefault={partner_id:'',brand_name:'',brand_logo_url:'',title:'',slug:'',description:'',bonus_type:'other',delivery_type:'code',code:'',affiliate_url:'',image_url:'',offer_value:'',terms:'',starts_at:'',expires_at:'',status:'draft',featured:false,sort_order:0,max_claims:'',bonus_access_type:'public'}
export function BonusEditor(){
 const {id}=useParams();const nav=useNavigate();const editing=!!id;const [f,setF]=useState<any>(bonusDefault);const [partners,setPartners]=useState<any[]>([])
 useEffect(()=>{void(async()=>{try{const {data,error}=await supabase.from('partners').select('id,name,status').order('name');if(error)throw error;setPartners(data??[]);if(editing){const {data:d,error:e}=await supabase.from('bonuses').select('*').eq('id',id).single();if(e)throw e;setF({...d,starts_at:fromIso(d.starts_at),expires_at:fromIso(d.expires_at),max_claims:d.max_claims??''})}}catch(e){toast.error(errorText(e))}})()},[id,editing])
 const set=(k:string,v:any)=>setF((x:any)=>({...x,[k]:v}))
 async function submit(e:any){e.preventDefault();try{if(!f.title.trim()||!f.slug.trim())throw new Error('Title and slug are required.');const common={p_partner_id:f.partner_id||null,p_title:f.title.trim(),p_slug:f.slug.trim(),p_description:f.description||null,p_bonus_type:f.bonus_type,p_delivery_type:f.delivery_type,p_code:f.code||null,p_affiliate_url:f.affiliate_url||null,p_image_url:f.image_url||null,p_offer_value:f.offer_value||null,p_terms:f.terms||null,p_starts_at:toIso(f.starts_at),p_expires_at:toIso(f.expires_at),p_featured:!!f.featured,p_sort_order:Number(f.sort_order)||0,p_max_claims:f.max_claims===''?null:Number(f.max_claims)};if(editing){const {error}=await supabase.rpc('admin_update_bonus',{p_bonus_id:id,...common,p_status:f.status});if(error)throw error;const {error:e2}=await supabase.from('bonuses').update({brand_name:f.brand_name.trim()||null,brand_logo_url:f.brand_logo_url||null,bonus_access_type:f.bonus_access_type||'public'}).eq('id',id);if(e2)throw e2}else{const {data,error}=await supabase.rpc('admin_create_bonus',{p_brand_name:f.brand_name.trim()||'Unknown Brand',p_brand_logo_url:f.brand_logo_url||null,...common});if(error)throw error;if(data?.id&&f.bonus_access_type&&f.bonus_access_type!=='public'){const {error:e2}=await supabase.from('bonuses').update({bonus_access_type:f.bonus_access_type}).eq('id',data.id);if(e2)throw e2}}toast.success(editing?'Bonus updated':'Bonus created');nav('/bonuses')}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><Back to="/bonuses" title={editing?'Edit Bonus':'Create Bonus'}/><form onSubmit={submit} className="flex flex-col gap-density-lg"><Card title="Identity"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Select label="Partner" value={f.partner_id} onChange={v=>set('partner_id',v)} options={partners.map(p=>({value:p.id,label:`${p.name}${p.status==='active'?'':' · '+p.status}`}))}/><Text label="Brand name" value={f.brand_name} onChange={v=>set('brand_name',v)} required/><Text label="Title" value={f.title} onChange={v=>set('title',v)} required/><Text label="Slug" value={f.slug} onChange={v=>set('slug',v)} required/></div></Card><Card title="Offer"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Select label="Bonus type" value={f.bonus_type} onChange={v=>set('bonus_type',v)} options={['deposit_bonus','free_bet','free_spin','cashback','promo_code','other'].map(v=>({value:v,label:v}))}/><Select label="Delivery" value={f.delivery_type} onChange={v=>set('delivery_type',v)} options={['code','link','code_and_link'].map(v=>({value:v,label:v}))}/><Select label="Access" value={f.bonus_access_type||'public'} onChange={v=>set('bonus_access_type',v)} options={['public','challenge','winner'].map(v=>({value:v,label:v}))}/><Select label="Status" value={f.status||'draft'} onChange={v=>set('status',v)} options={['draft','active','paused','expired','archived'].map(v=>({value:v,label:v}))}/><Text label="Promo code" value={f.code} onChange={v=>set('code',v)}/><Text label="Affiliate URL" value={f.affiliate_url} onChange={v=>set('affiliate_url',v)}/><Text label="Offer value" value={f.offer_value} onChange={v=>set('offer_value',v)}/><Text label="Max claims" value={f.max_claims} onChange={v=>set('max_claims',v)} type="number"/><Text label="Starts" value={f.starts_at} onChange={v=>set('starts_at',v)} type="datetime-local"/><Text label="Expires" value={f.expires_at} onChange={v=>set('expires_at',v)} type="datetime-local"/><Text label="Sort order" value={f.sort_order} onChange={v=>set('sort_order',v)} type="number"/><Toggle label="Featured" checked={!!f.featured} onChange={v=>set('featured',v)}/></div></Card><Card title="Content"><div className="grid gap-density-md md:grid-cols-2"><Area label="Description" value={f.description} onChange={v=>set('description',v)}/><Area label="Terms" value={f.terms} onChange={v=>set('terms',v)}/><Text label="Brand logo URL" value={f.brand_logo_url} onChange={v=>set('brand_logo_url',v)}/><Text label="Image URL" value={f.image_url} onChange={v=>set('image_url',v)}/></div></Card><Actions to="/bonuses"/></form></div>
}

const giveawayDefault={challenge_id:'',slug:'',title:'',subtitle:'',description:'',giveaway_type:'general',status:'draft',starts_at:'',ends_at:'',featured:false,sort_order:0,image_url:'',cover_url:'',badge_text:'',prize_headline:'',participant_label:'',show_participant_count:true,show_winner_count:true,display_type:'general'}
export function GiveawaysPage(){
 const [rows,setRows]=useState<any[]>([]);const [loading,setLoading]=useState(true)
 const load=async()=>{setLoading(true);try{const {data,error}=await supabase.from('giveaways').select('id,challenge_id,slug,title,giveaway_type,status,starts_at,ends_at,display_type,featured,prize_headline').order('sort_order').order('created_at',{ascending:false});if(error)throw error;setRows(data??[])}catch(e){toast.error(errorText(e))}finally{setLoading(false)}}
 useEffect(()=>{void load()},[])
 async function remove(r:any){if(!window.confirm('Delete this giveaway?'))return;try{const checks=await Promise.all([supabase.from('challenge_entries').select('id',{count:'exact',head:true}).eq('challenge_id',r.challenge_id),supabase.from('challenge_tasks').select('id',{count:'exact',head:true}).eq('challenge_id',r.challenge_id),supabase.from('challenge_prizes').select('id',{count:'exact',head:true}).eq('challenge_id',r.challenge_id),supabase.from('challenge_winners').select('id',{count:'exact',head:true}).eq('challenge_id',r.challenge_id),supabase.from('pickrush_contests').select('id',{count:'exact',head:true}).eq('challenge_id',r.challenge_id),supabase.from('prize_pool_campaigns').select('id',{count:'exact',head:true}).eq('challenge_id',r.challenge_id)]);const bad=checks.find(x=>x.error);if(bad?.error)throw bad.error;if(checks.some(x=>Number(x.count??0)>0))throw new Error('This giveaway has participation history. End or cancel it instead of deleting it.');const {error}=await supabase.from('giveaways').delete().eq('id',r.id);if(error)throw error;const {error:ce}=await supabase.from('challenges').delete().eq('id',r.challenge_id);if(ce)throw ce;toast.success('Giveaway deleted');await load()}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Giveaways" description="Manage giveaway presentation and its linked challenge." actions={<><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button asChild><Link to="/giveaways/new"><Plus className="h-4 w-4"/>Create giveaway</Link></Button></>}/><Card title={`Giveaways (${rows.length})`}><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Title</th><th>Type</th><th>Display</th><th>Status</th><th>Starts</th><th>Ends</th><th/></tr></thead><tbody>{rows.map(r=><tr key={r.id} className="border-b border-border/70"><td className="py-2 font-medium">{r.title}</td><td>{r.giveaway_type}</td><td>{r.display_type}</td><td><StatusBadge status={r.status} dense/></td><td>{dateText(r.starts_at)}</td><td>{dateText(r.ends_at)}</td><td className="text-right whitespace-nowrap"><Button asChild size="sm" variant="ghost"><Link to={`/giveaways/${r.id}/edit`}>Manage</Link></Button><Button size="sm" variant="ghost" onClick={()=>void remove(r)}><Trash2 className="h-3.5 w-3.5"/></Button></td></tr>)}</tbody></table>{!rows.length&&<Empty>{loading?'Loading…':'No giveaways yet.'}</Empty>}</div></Card></div>
}

export function GiveawayEditor(){
 const {id}=useParams();const nav=useNavigate();const editing=!!id;const [f,setF]=useState<any>(giveawayDefault);const [challenges,setChallenges]=useState<any[]>([]);const [tasks,setTasks]=useState<any[]>([]);const [prizes,setPrizes]=useState<any[]>([])
 const set=(k:string,v:any)=>setF((x:any)=>({...x,[k]:v}));
 const loadRelated=async(challengeId:string)=>{if(!challengeId){setTasks([]);setPrizes([]);return}try{const [t,p]=await Promise.all([supabase.from('challenge_tasks').select('id,title,task_type,verification_method,task_order').eq('challenge_id',challengeId).order('task_order'),supabase.from('challenge_prizes').select('id,title,prize_type,award_trigger,quantity,sort_order').eq('challenge_id',challengeId).order('sort_order')]);if(t.error)throw t.error;if(p.error)throw p.error;setTasks(t.data??[]);setPrizes(p.data??[])}catch(e){toast.error(errorText(e))}}
 useEffect(()=>{void(async()=>{try{const {data,error}=await supabase.from('challenges').select('id,title,status').order('created_at',{ascending:false});if(error)throw error;setChallenges(data??[]);if(editing){const {data:d,error:e}=await supabase.from('giveaways').select('*').eq('id',id).single();if(e)throw e;setF({...d,starts_at:fromIso(d.starts_at),ends_at:fromIso(d.ends_at)});await loadRelated(d.challenge_id)}}catch(e){toast.error(errorText(e))}})()},[id,editing])
 async function submit(e:any){e.preventDefault();try{if(!f.title.trim()||!f.slug.trim())throw new Error('Title and slug are required.');let challengeId=f.challenge_id;if(!challengeId&&!editing){const {data,error}=await supabase.from('challenges').insert({slug:`${f.slug}-challenge`,title:f.title.trim(),description:f.description||null,challenge_type:f.giveaway_type==='prediction'?'prediction':f.giveaway_type==='social'?'social':'custom',status:'draft',starts_at:toIso(f.starts_at),ends_at:toIso(f.ends_at),winner_selection_method:'random',winner_count:1,reveal_winners:true,featured:!!f.featured,sort_order:Number(f.sort_order)||0,image_url:f.image_url||null,metadata:{},engine_key:'custom_v1'}).select('id').single();if(error)throw error;challengeId=data.id}if(!challengeId)throw new Error('A challenge is required.');const payload={challenge_id:challengeId,slug:f.slug.trim(),title:f.title.trim(),subtitle:f.subtitle||null,description:f.description||null,giveaway_type:f.giveaway_type,status:f.status,starts_at:toIso(f.starts_at),ends_at:toIso(f.ends_at),featured:!!f.featured,sort_order:Number(f.sort_order)||0,image_url:f.image_url||null,cover_url:f.cover_url||null,badge_text:f.badge_text||null,prize_headline:f.prize_headline||null,participant_label:f.participant_label||null,show_participant_count:!!f.show_participant_count,show_winner_count:!!f.show_winner_count,display_type:f.display_type||'general'};const {error}=editing?await supabase.from('giveaways').update(payload).eq('id',id):await supabase.from('giveaways').insert(payload);if(error)throw error;toast.success(editing?'Giveaway updated':'Giveaway created');nav('/giveaways')}catch(e){toast.error(errorText(e))}}
 async function removeChild(table:string,rowId:string){if(!window.confirm('Delete this item?'))return;try{const {error}=await supabase.from(table).delete().eq('id',rowId);if(error)throw error;await loadRelated(f.challenge_id);toast.success('Deleted')}catch(e){toast.error(errorText(e))}}
 async function addTask(){try{if(!f.challenge_id)throw new Error('Select a challenge first.');const {error}=await supabase.from('challenge_tasks').insert({challenge_id:f.challenge_id,task_key:`task_${Date.now()}`,title:'New task',description:null,task_type:'custom',verification_method:'manual',is_required:true,task_order:tasks.length,config:{},starts_at:null,ends_at:null,metadata:{}});if(error)throw error;await loadRelated(f.challenge_id)}catch(e){toast.error(errorText(e))}}
 async function addPrize(){try{if(!f.challenge_id)throw new Error('Select a challenge first.');const {error}=await supabase.from('challenge_prizes').insert({challenge_id:f.challenge_id,title:'New prize',description:null,prize_type:'points',award_trigger:'winner',quantity:1,points_amount:0,sort_order:prizes.length,custom_data:{},metadata:{}});if(error)throw error;await loadRelated(f.challenge_id)}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><Back to="/giveaways" title={editing?'Manage Giveaway':'Create Giveaway'}/><form onSubmit={submit} className="flex flex-col gap-density-lg"><Card title="Giveaway"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Text label="Title" value={f.title} onChange={v=>set('title',v)} required/><Text label="Slug" value={f.slug} onChange={v=>set('slug',v)} required/><Select label="Challenge" value={f.challenge_id||''} onChange={v=>{set('challenge_id',v);void loadRelated(v)}} options={[{value:'',label:'Create automatically on save'},...challenges.map(c=>({value:c.id,label:`${c.title} · ${c.status}`}))]}/><Select label="Giveaway type" value={f.giveaway_type} onChange={v=>set('giveaway_type',v)} options={['general','social','telegram','prediction','random_draw','mixed','tournament','special'].map(v=>({value:v,label:v}))}/><Select label="Display type" value={f.display_type||'general'} onChange={v=>set('display_type',v)} options={['general','social','telegram','prediction','random_draw','mixed','tournament','pickrush','prize_pool','special','custom'].map(v=>({value:v,label:v}))}/><Select label="Status" value={f.status} onChange={v=>set('status',v)} options={['draft','active','paused','ended','cancelled'].map(v=>({value:v,label:v}))}/><Text label="Starts" value={f.starts_at} onChange={v=>set('starts_at',v)} type="datetime-local"/><Text label="Ends" value={f.ends_at} onChange={v=>set('ends_at',v)} type="datetime-local"/><Text label="Sort order" value={f.sort_order} onChange={v=>set('sort_order',v)} type="number"/><Toggle label="Featured" checked={!!f.featured} onChange={v=>set('featured',v)}/></div></Card><Card title="Content"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Area label="Description" value={f.description} onChange={v=>set('description',v)}/><Text label="Image URL" value={f.image_url} onChange={v=>set('image_url',v)}/><Text label="Cover URL" value={f.cover_url} onChange={v=>set('cover_url',v)}/><Text label="Badge text" value={f.badge_text} onChange={v=>set('badge_text',v)}/><Text label="Prize headline" value={f.prize_headline} onChange={v=>set('prize_headline',v)}/><Text label="Participant label" value={f.participant_label} onChange={v=>set('participant_label',v)}/></div></Card><Actions to="/giveaways"/></form>{editing&&<div className="grid gap-density-lg xl:grid-cols-2"><Card title={`Tasks (${tasks.length})`} actions={<Button size="sm" onClick={()=>void addTask()}><Plus className="h-3.5 w-3.5"/>Add task</Button>}>{tasks.length?tasks.map(t=><div key={t.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{t.title}</div><div className="text-xs text-muted-foreground">{t.task_type} · {t.verification_method}</div></div><Button size="sm" variant="ghost" onClick={()=>void removeChild('challenge_tasks',t.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>):<Empty>No tasks.</Empty>}</Card><Card title={`Prizes (${prizes.length})`} actions={<Button size="sm" onClick={()=>void addPrize()}><Plus className="h-3.5 w-3.5"/>Add prize</Button>}>{prizes.length?prizes.map(p=><div key={p.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{p.title}</div><div className="text-xs text-muted-foreground">{p.prize_type} · {p.award_trigger}</div></div><Button size="sm" variant="ghost" onClick={()=>void removeChild('challenge_prizes',p.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>):<Empty>No prizes.</Empty>}</Card></div>}</div>
}

const closeRules=['time_only','participant_limit_only','time_or_limit','time_and_limit','manual'].map(v=>({value:v,label:v}))
export function PickRushPage(){
 const [rows,setRows]=useState<any[]>([]);const [loading,setLoading]=useState(true)
 const load=async()=>{setLoading(true);try{const {data,error}=await supabase.from('pickrush_contests').select('id,challenge_id,status,starts_at,ends_at,participant_limit,required_matches,min_total_odds,max_total_odds,virtual_stake,campaign_percent,max_entries_per_user').order('starts_at',{ascending:false});if(error)throw error;setRows(data??[])}catch(e){toast.error(errorText(e))}finally{setLoading(false)}}
 useEffect(()=>{void load()},[])
 async function lifecycle(fn:'open_pickrush'|'lock_pickrush_contest'|'close_pickrush'|'finalize_pickrush_contest',id:string){try{const args=fn==='close_pickrush'?{p_contest_id:id,p_reason:'admin action'}:{p_contest_id:id};const {error}=await supabase.rpc(fn,args);if(error)throw error;toast.success('Pick Rush operation completed');await load()}catch(e){toast.error(errorText(e))}}
 async function remove(id:string){if(!window.confirm('Delete this Pick Rush contest?'))return;try{const {error}=await supabase.from('pickrush_contests').delete().eq('id',id);if(error)throw error;toast.success('Pick Rush deleted');await load()}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Pick Rush" description="Manage contests and lifecycle state." actions={<><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button asChild><Link to="/pickrush/new"><Plus className="h-4 w-4"/>Create contest</Link></Button></>}/><Card title={`Contests (${rows.length})`}><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Contest</th><th>Status</th><th>Schedule</th><th>Matches</th><th>Odds</th><th>Stake</th><th/></tr></thead><tbody>{rows.map(r=><tr key={r.id} className="border-b border-border/70"><td className="py-2">{r.id.slice(0,8)}</td><td><StatusBadge status={r.status} dense/></td><td>{dateText(r.starts_at)}<br/>{dateText(r.ends_at)}</td><td>{r.required_matches}</td><td>{r.min_total_odds}–{r.max_total_odds}</td><td>{r.virtual_stake}</td><td className="text-right whitespace-nowrap"><Button asChild size="sm" variant="ghost"><Link to={`/pickrush/${r.id}/edit`}>Edit</Link></Button><Button size="sm" variant="ghost" onClick={()=>void lifecycle('open_pickrush',r.id)} disabled={['open','full'].includes(r.status)}><Play className="h-3.5 w-3.5"/></Button><Button size="sm" variant="ghost" onClick={()=>void lifecycle('lock_pickrush_contest',r.id)}><LockKeyhole className="h-3.5 w-3.5"/></Button><Button size="sm" variant="ghost" onClick={()=>void lifecycle('close_pickrush',r.id)}><PowerOff className="h-3.5 w-3.5"/></Button><Button size="sm" variant="ghost" onClick={()=>void lifecycle('finalize_pickrush_contest',r.id)}><Trophy className="h-3.5 w-3.5"/></Button><Button size="sm" variant="ghost" onClick={()=>void remove(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></td></tr>)}</tbody></table>{!rows.length&&<Empty>{loading?'Loading…':'No Pick Rush contests yet.'}</Empty>}</div></Card></div>
}
export function PickRushEditor(){
 const {id}=useParams();const nav=useNavigate();const editing=!!id;const [partners,setPartners]=useState<any[]>([]);const [f,setF]=useState<any>({title:'',slug:'',description:'',starts_at:'',ends_at:'',participant_limit:'',close_rule:'time_only',platform_partner_id:'',platform_url:'',required_matches:1,min_total_odds:1,max_total_odds:10,virtual_stake:1,image_url:'',metadata:'{}'})
 const set=(k:string,v:any)=>setF((x:any)=>({...x,[k]:v}))
 useEffect(()=>{void(async()=>{try{const {data,error}=await supabase.from('partners').select('id,name').order('name');if(error)throw error;setPartners(data??[]);if(editing){const {data:d,error:e}=await supabase.from('pickrush_contests').select('*').eq('id',id).single();if(e)throw e;setF({...d,starts_at:fromIso(d.starts_at),ends_at:fromIso(d.ends_at),metadata:JSON.stringify(d.metadata??{},null,2)})}}catch(e){toast.error(errorText(e))}})()},[id,editing])
 async function submit(e:any){e.preventDefault();try{const vals={starts_at:toIso(f.starts_at),ends_at:toIso(f.ends_at),participant_limit:f.participant_limit===''?null:Number(f.participant_limit),close_rule:f.close_rule,platform_partner_id:f.platform_partner_id||null,platform_url:f.platform_url||null,required_matches:Number(f.required_matches),min_total_odds:Number(f.min_total_odds),max_total_odds:Number(f.max_total_odds),virtual_stake:Number(f.virtual_stake),image_url:f.image_url||null,metadata:JSON.parse(f.metadata||'{}')};if(!f.title?.trim()||!f.slug?.trim())throw new Error('Title and slug are required.');if(!Number.isFinite(vals.max_total_odds)||!Number.isFinite(vals.min_total_odds))throw new Error('Minimum and maximum total odds are required.');if(editing){const {error}=await supabase.from('pickrush_contests').update(vals).eq('id',id);if(error)throw error}else{const {error}=await supabase.rpc('create_pickrush_contest',{p_title:f.title.trim(),p_slug:f.slug.trim(),p_description:f.description||null,p_starts_at:vals.starts_at,p_ends_at:vals.ends_at,p_participant_limit:vals.participant_limit,p_close_rule:vals.close_rule,p_platform_partner_id:vals.platform_partner_id,p_platform_url:vals.platform_url,p_required_matches:vals.required_matches,p_min_total_odds:vals.min_total_odds,p_max_total_odds:vals.max_total_odds,p_virtual_stake:vals.virtual_stake,p_image_url:vals.image_url,p_metadata:vals.metadata});if(error)throw error}toast.success(editing?'Pick Rush updated':'Pick Rush created');nav('/pickrush')}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><Back to="/pickrush" title={editing?'Edit Pick Rush':'Create Pick Rush'}/><form onSubmit={submit} className="flex flex-col gap-density-lg"><Card title="Contest configuration"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Text label="Title" value={f.title} onChange={v=>set('title',v)} required/><Text label="Slug" value={f.slug} onChange={v=>set('slug',v)} required/><Text label="Starts" value={f.starts_at} onChange={v=>set('starts_at',v)} type="datetime-local" required/><Text label="Ends" value={f.ends_at} onChange={v=>set('ends_at',v)} type="datetime-local" required/><Text label="Participant limit" value={f.participant_limit} onChange={v=>set('participant_limit',v)} type="number"/><Select label="Close rule" value={f.close_rule} onChange={v=>set('close_rule',v)} options={closeRules}/><Select label="Platform partner" value={f.platform_partner_id||''} onChange={v=>set('platform_partner_id',v)} options={[{value:'',label:'No partner'},...partners.map(p=>({value:p.id,label:p.name}))]}/><Text label="Platform URL" value={f.platform_url} onChange={v=>set('platform_url',v)}/><Text label="Required matches" value={f.required_matches} onChange={v=>set('required_matches',v)} type="number" required/><Text label="Minimum total odds" value={f.min_total_odds} onChange={v=>set('min_total_odds',v)} type="number" required/><Text label="Maximum total odds" value={f.max_total_odds} onChange={v=>set('max_total_odds',v)} type="number" required/><Text label="Virtual stake" value={f.virtual_stake} onChange={v=>set('virtual_stake',v)} type="number" required/><Text label="Image URL" value={f.image_url} onChange={v=>set('image_url',v)}/></div></Card><Card title="Description & metadata"><div className="grid gap-density-md md:grid-cols-2"><Area label="Description" value={f.description} onChange={v=>set('description',v)}/><Area label="Metadata JSON" value={f.metadata} onChange={v=>set('metadata',v)}/></div></Card><Actions to="/pickrush"/></form></div>
}

export function PrizePoolPage(){
 const [rows,setRows]=useState<any[]>([]);const [loading,setLoading]=useState(true)
 const load=async()=>{setLoading(true);try{const {data,error}=await supabase.from('prize_pool_campaigns').select('id,slug,title,status,starts_at,ends_at,process_at,pool_amount,currency,rewarded_positions,leaderboard_metric,distribution_method,eligibility_mode').order('starts_at',{ascending:false});if(error)throw error;setRows(data??[])}catch(e){toast.error(errorText(e))}finally{setLoading(false)}}
 useEffect(()=>{void load()},[])
 async function process(id:string){try{const {error}=await supabase.rpc('process_prize_pool',{p_campaign_id:id,p_force:true});if(error)throw error;toast.success('Prize pool processed');await load()}catch(e){toast.error(errorText(e))}}
 async function remove(id:string){if(!window.confirm('Delete this Prize Pool campaign?'))return;try{const {error}=await supabase.from('prize_pool_campaigns').delete().eq('id',id);if(error)throw error;toast.success('Prize Pool deleted');await load()}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Prize Pool" description="Manage prize pool campaigns, processing and related configuration." actions={<><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button asChild><Link to="/prizepool/new"><Plus className="h-4 w-4"/>Create pool</Link></Button></>}/><Card title={`Campaigns (${rows.length})`}><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Campaign</th><th>Status</th><th>Pool</th><th>Positions</th><th>Process</th><th/></tr></thead><tbody>{rows.map(r=><tr key={r.id} className="border-b border-border/70"><td className="py-2"><div className="font-medium">{r.title}</div><div className="text-xs text-muted-foreground">{r.slug}</div></td><td><StatusBadge status={r.status} dense/></td><td>{r.pool_amount} {r.currency}</td><td>{r.rewarded_positions}</td><td>{dateText(r.process_at)}</td><td className="text-right whitespace-nowrap"><Button asChild size="sm" variant="ghost"><Link to={`/prizepool/${r.id}/edit`}>Manage</Link></Button><Button size="sm" variant="ghost" onClick={()=>void process(r.id)}>Process</Button><Button size="sm" variant="ghost" onClick={()=>void remove(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></td></tr>)}</tbody></table>{!rows.length&&<Empty>{loading?'Loading…':'No Prize Pool campaigns yet.'}</Empty>}</div></Card></div>
}
export function PrizePoolEditor(){
 const {id}=useParams();const nav=useNavigate();const editing=!!id;const [f,setF]=useState<any>({slug:'',title:'',subtitle:'',description:'',starts_at:'',ends_at:'',process_at:'',pool_amount:'',currency:'USD',rewarded_positions:100,leaderboard_metric:'current_balance',distribution_method:'equal',eligibility_mode:'joined_only',max_entries_per_user:1,min_account_age_days:'',featured:false,sort_order:0,image_url:'',cover_url:'',badge_text:'',prize_headline:'',participant_label:'',metadata:'{}',eligibility_rules:'{}'});const [tiers,setTiers]=useState<any[]>([]);const [rules,setRules]=useState<any[]>([])
 const set=(k:string,v:any)=>setF((x:any)=>({...x,[k]:v}));const related=async()=>{if(!id)return;try{const [t,r]=await Promise.all([supabase.from('prize_pool_reward_tiers').select('*').eq('campaign_id',id).order('sort_order'),supabase.from('prize_pool_eligibility_rules').select('*').eq('campaign_id',id).order('sort_order')]);if(t.error)throw t.error;if(r.error)throw r.error;setTiers(t.data??[]);setRules(r.data??[])}catch(e){toast.error(errorText(e))}}
 useEffect(()=>{void(async()=>{if(!editing)return;try{const {data,error}=await supabase.from('prize_pool_campaigns').select('*').eq('id',id).single();if(error)throw error;setF({...data,starts_at:fromIso(data.starts_at),ends_at:fromIso(data.ends_at),process_at:fromIso(data.process_at),metadata:JSON.stringify(data.metadata??{},null,2),eligibility_rules:JSON.stringify(data.eligibility_rules??{},null,2)});await related()}catch(e){toast.error(errorText(e))}})()},[id,editing])
 async function submit(e:any){e.preventDefault();try{if(!f.title.trim()||!f.slug.trim())throw new Error('Title and slug are required.');const vals={slug:f.slug.trim(),title:f.title.trim(),description:f.description||null,starts_at:toIso(f.starts_at),ends_at:toIso(f.ends_at),process_at:toIso(f.process_at),pool_amount:Number(f.pool_amount),currency:f.currency.toUpperCase(),rewarded_positions:Number(f.rewarded_positions),leaderboard_metric:f.leaderboard_metric,distribution_method:f.distribution_method,eligibility_mode:f.eligibility_mode,max_entries_per_user:Number(f.max_entries_per_user),min_account_age_days:f.min_account_age_days===''?null:Number(f.min_account_age_days),featured:!!f.featured,sort_order:Number(f.sort_order)||0,subtitle:f.subtitle||null,image_url:f.image_url||null,cover_url:f.cover_url||null,badge_text:f.badge_text||null,prize_headline:f.prize_headline||null,participant_label:f.participant_label||null,metadata:JSON.parse(f.metadata||'{}'),eligibility_rules:JSON.parse(f.eligibility_rules||'{}')};if(!editing){const {error}=await supabase.rpc('create_prize_pool_campaign',{p_slug:vals.slug,p_title:vals.title,p_description:vals.description,p_starts_at:vals.starts_at,p_ends_at:vals.ends_at,p_process_at:vals.process_at,p_pool_amount:vals.pool_amount,p_currency:vals.currency,p_rewarded_positions:vals.rewarded_positions,p_leaderboard_metric:vals.leaderboard_metric});if(error)throw error}else{const {error}=await supabase.from('prize_pool_campaigns').update(vals).eq('id',id);if(error)throw error}toast.success(editing?'Prize Pool updated':'Prize Pool created');nav('/prizepool')}catch(e){toast.error(errorText(e))}}
 async function addTier(){try{if(!id)throw new Error('Save the campaign first.');const {error}=await supabase.from('prize_pool_reward_tiers').insert({campaign_id:id,rank_from:1,rank_to:1,reward_amount:1,currency:f.currency.toUpperCase(),title:'New tier',sort_order:tiers.length});if(error)throw error;await related()}catch(e){toast.error(errorText(e))}}
 async function addRule(){try{if(!id)throw new Error('Save the campaign first.');const {error}=await supabase.from('prize_pool_eligibility_rules').insert({campaign_id:id,rule_key:`rule_${Date.now()}`,rule_type:'account_age',operator:'gte',value:{},is_required:true,enabled:true,sort_order:rules.length,metadata:{}});if(error)throw error;await related()}catch(e){toast.error(errorText(e))}}
 async function removeChild(table:string,rowId:string){if(!window.confirm('Delete this item?'))return;try{const {error}=await supabase.from(table).delete().eq('id',rowId);if(error)throw error;await related()}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><Back to="/prizepool" title={editing?'Manage Prize Pool':'Create Prize Pool'}/><form onSubmit={submit} className="flex flex-col gap-density-lg"><Card title="Campaign"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Text label="Title" value={f.title} onChange={v=>set('title',v)} required/><Text label="Slug" value={f.slug} onChange={v=>set('slug',v)} required/><Text label="Starts" value={f.starts_at} onChange={v=>set('starts_at',v)} type="datetime-local" required/><Text label="Ends" value={f.ends_at} onChange={v=>set('ends_at',v)} type="datetime-local" required/><Text label="Process at" value={f.process_at} onChange={v=>set('process_at',v)} type="datetime-local" required/><Text label="Pool amount" value={f.pool_amount} onChange={v=>set('pool_amount',v)} type="number" required/><Text label="Currency" value={f.currency} onChange={v=>set('currency',v)} required/><Text label="Rewarded positions" value={f.rewarded_positions} onChange={v=>set('rewarded_positions',v)} type="number" required/><Select label="Leaderboard metric" value={f.leaderboard_metric} onChange={v=>set('leaderboard_metric',v)} options={['current_balance','lifetime_earned'].map(v=>({value:v,label:v}))}/><Select label="Distribution" value={f.distribution_method} onChange={v=>set('distribution_method',v)} options={['equal','tiered'].map(v=>({value:v,label:v}))}/><Select label="Eligibility" value={f.eligibility_mode} onChange={v=>set('eligibility_mode',v)} options={['open','account_age','joined_only'].map(v=>({value:v,label:v}))}/><Text label="Max entries/user" value={f.max_entries_per_user} onChange={v=>set('max_entries_per_user',v)} type="number"/><Text label="Min account age days" value={f.min_account_age_days} onChange={v=>set('min_account_age_days',v)} type="number"/><Toggle label="Featured" checked={!!f.featured} onChange={v=>set('featured',v)}/></div></Card><Card title="Presentation"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Text label="Subtitle" value={f.subtitle} onChange={v=>set('subtitle',v)}/><Text label="Image URL" value={f.image_url} onChange={v=>set('image_url',v)}/><Text label="Cover URL" value={f.cover_url} onChange={v=>set('cover_url',v)}/><Text label="Badge text" value={f.badge_text} onChange={v=>set('badge_text',v)}/><Text label="Prize headline" value={f.prize_headline} onChange={v=>set('prize_headline',v)}/><Text label="Participant label" value={f.participant_label} onChange={v=>set('participant_label',v)}/><Area label="Description" value={f.description} onChange={v=>set('description',v)}/><Area label="Metadata JSON" value={f.metadata} onChange={v=>set('metadata',v)}/><Area label="Eligibility rules JSON" value={f.eligibility_rules} onChange={v=>set('eligibility_rules',v)}/></div></Card><Actions to="/prizepool"/></form>{editing&&<div className="grid gap-density-lg xl:grid-cols-2"><Card title={`Reward tiers (${tiers.length})`} actions={<Button size="sm" onClick={()=>void addTier()}><Plus className="h-3.5 w-3.5"/>Add tier</Button>}>{tiers.length?tiers.map(t=><div key={t.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div>#{t.rank_from}–{t.rank_to} · {t.reward_amount} {t.currency}</div><Button size="sm" variant="ghost" onClick={()=>void removeChild('prize_pool_reward_tiers',t.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>):<Empty>No tiers.</Empty>}</Card><Card title={`Eligibility rules (${rules.length})`} actions={<Button size="sm" onClick={()=>void addRule()}><Plus className="h-3.5 w-3.5"/>Add rule</Button>}>{rules.length?rules.map(r=><div key={r.id} className="mb-2 flex items-center justify-between rounded-md border border-border p-3"><div><div className="font-medium">{r.title||r.rule_key}</div><div className="text-xs text-muted-foreground">{r.rule_type} {r.operator}</div></div><Button size="sm" variant="ghost" onClick={()=>void removeChild('prize_pool_eligibility_rules',r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div>):<Empty>No eligibility rules.</Empty>}</Card></div>}</div>
}

export function BookmakersRadarPage(){
 const [rows,setRows]=useState<any[]>([]);const [loading,setLoading]=useState(true)
 const load=async()=>{setLoading(true);try{const {data,error}=await supabase.from('bookmakers_radar').select('id,partner_id,name,slug,status,radar_score,risk_level,confidence_level,evidence_strength,current_signal,trend,verified,priority,featured,license_verified,is_sharp,data_provider_enabled,discovery_source').order('priority').order('name');if(error)throw error;setRows(data??[])}catch(e){toast.error(errorText(e))}finally{setLoading(false)}}
 useEffect(()=>{void load()},[])
 async function recompute(id?:string){try{const {error}=id?await supabase.rpc('recompute_bookmaker_radar',{p_bookmaker_id:id}):await supabase.rpc('recompute_all_bookmakers_radar');if(error)throw error;toast.success('Radar recomputed');await load()}catch(e){toast.error(errorText(e))}}
 async function remove(id:string){if(!window.confirm('Delete this bookmaker?'))return;try{const {error}=await supabase.from('bookmakers_radar').delete().eq('id',id);if(error)throw error;toast.success('Bookmaker deleted');await load()}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Bookmakers Radar" description="Manage bookmakers and radar controls." actions={<><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button variant="outline" onClick={()=>void recompute()}>Recompute all</Button><Button asChild><Link to="/bookmakersradar/new"><Plus className="h-4 w-4"/>Create bookmaker</Link></Button></>}/><Card title={`Bookmakers (${rows.length})`}><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{rows.map(r=><div key={r.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div><div className="font-medium">{r.name}</div><div className="text-xs text-muted-foreground">{r.slug} · priority {r.priority}</div></div><StatusBadge status={r.status} dense/></div><div className="mt-2 text-xs text-muted-foreground">Radar {r.radar_score??'—'} · risk {r.risk_level} · signal {r.current_signal}</div><div className="mt-2 flex justify-end gap-1"><Button asChild size="sm" variant="ghost"><Link to={`/bookmakersradar/${r.id}/edit`}>Edit</Link></Button><Button size="sm" variant="ghost" onClick={()=>void recompute(r.id)}>Recompute</Button><Button size="sm" variant="ghost" onClick={()=>void remove(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div></div>)}{!rows.length&&<Empty>{loading?'Loading…':'No bookmakers yet.'}</Empty>}</div></Card></div>
}
export function BookmakerEditor(){
 const {id}=useParams();const nav=useNavigate();const editing=!!id;const [partners,setPartners]=useState<any[]>([]);const [f,setF]=useState<any>({partner_id:'',name:'',slug:'',short_name:'',logo_url:'',cover_url:'',website:'',license_name:'',license_verified:false,country:'',description:'',status:'active',featured:false,sort_order:0,discovery_source:'admin',verified:false,priority:100,is_sharp:false,data_provider_enabled:true,metadata:'{}'});const set=(k:string,v:any)=>setF((x:any)=>({...x,[k]:v}))
 useEffect(()=>{void(async()=>{try{const {data,error}=await supabase.from('partners').select('id,name').order('name');if(error)throw error;setPartners(data??[]);if(editing){const {data:d,error:e}=await supabase.from('bookmakers_radar').select('*').eq('id',id).single();if(e)throw e;setF({...d,metadata:JSON.stringify(d.metadata??{},null,2)})}}catch(e){toast.error(errorText(e))}})()},[id,editing])
 async function submit(e:any){e.preventDefault();try{if(!f.name.trim()||!f.slug.trim())throw new Error('Name and slug are required.');const payload={partner_id:f.partner_id||null,name:f.name.trim(),slug:f.slug.trim(),short_name:f.short_name||null,logo_url:f.logo_url||null,cover_url:f.cover_url||null,website:f.website||null,license_name:f.license_name||null,license_verified:!!f.license_verified,country:f.country||null,description:f.description||null,status:f.status,featured:!!f.featured,sort_order:Number(f.sort_order)||0,discovery_source:f.discovery_source||'admin',verified:!!f.verified,priority:Number(f.priority)||100,is_sharp:!!f.is_sharp,data_provider_enabled:!!f.data_provider_enabled,metadata:JSON.parse(f.metadata||'{}')};const q=editing?supabase.from('bookmakers_radar').update(payload).eq('id',id):supabase.from('bookmakers_radar').insert(payload);const {error}=await q;if(error)throw error;toast.success(editing?'Bookmaker updated':'Bookmaker created');nav('/bookmakersradar')}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><Back to="/bookmakersradar" title={editing?'Edit Bookmaker':'Create Bookmaker'}/><form onSubmit={submit} className="flex flex-col gap-density-lg"><Card title="Identity"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Select label="Partner" value={f.partner_id||''} onChange={v=>set('partner_id',v)} options={[{value:'',label:'No partner'},...partners.map(p=>({value:p.id,label:p.name}))]}/><Text label="Name" value={f.name} onChange={v=>set('name',v)} required/><Text label="Slug" value={f.slug} onChange={v=>set('slug',v)} required/><Text label="Short name" value={f.short_name} onChange={v=>set('short_name',v)}/><Text label="Website" value={f.website} onChange={v=>set('website',v)}/><Text label="Country" value={f.country} onChange={v=>set('country',v)}/><Text label="License" value={f.license_name} onChange={v=>set('license_name',v)}/><Select label="Status" value={f.status} onChange={v=>set('status',v)} options={['active','inactive','archived'].map(v=>({value:v,label:v}))}/><Text label="Priority" value={f.priority} onChange={v=>set('priority',v)} type="number"/><Text label="Logo URL" value={f.logo_url} onChange={v=>set('logo_url',v)}/><Text label="Cover URL" value={f.cover_url} onChange={v=>set('cover_url',v)}/><Select label="Discovery source" value={f.discovery_source||'admin'} onChange={v=>set('discovery_source',v)} options={['admin','system','user_report','import'].map(v=>({value:v,label:v}))}/></div></Card><Card title="Radar controls"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Toggle label="Verified" checked={!!f.verified} onChange={v=>set('verified',v)}/><Toggle label="License verified" checked={!!f.license_verified} onChange={v=>set('license_verified',v)}/><Toggle label="Featured" checked={!!f.featured} onChange={v=>set('featured',v)}/><Toggle label="Sharp" checked={!!f.is_sharp} onChange={v=>set('is_sharp',v)}/><Toggle label="Data provider enabled" checked={!!f.data_provider_enabled} onChange={v=>set('data_provider_enabled',v)}/></div><div className="mt-density-md grid gap-density-md md:grid-cols-2"><Area label="Description" value={f.description} onChange={v=>set('description',v)}/><Area label="Metadata JSON" value={f.metadata} onChange={v=>set('metadata',v)}/></div></Card><Actions to="/bookmakersradar"/></form></div>
}

export function LeaderboardsPage(){
 const [rows,setRows]=useState<any[]>([]);const [live,setLive]=useState<any[]>([]);const [loading,setLoading]=useState(true)
 const load=async()=>{setLoading(true);try{const [bots,lb]=await Promise.all([supabase.from('leaderboard_bots').select('id,username,full_name,points,is_active,status,country,city').order('points',{ascending:false}),supabase.rpc('get_leaderboard',{p_limit:100,p_offset:0})]);if(bots.error)throw bots.error;if(lb.error)throw lb.error;setRows(bots.data??[]);setLive(Array.isArray(lb.data)?lb.data:[])}catch(e){toast.error(errorText(e))}finally{setLoading(false)}}
 useEffect(()=>{void load()},[])
 async function remove(id:string){if(!window.confirm('Delete this leaderboard bot?'))return;try{const {error}=await supabase.from('leaderboard_bots').delete().eq('id',id);if(error)throw error;toast.success('Bot deleted');await load()}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><PageHeader title="Leaderboards" description="Live leaderboard is read-only; bot administration is CRUD." actions={<><Button variant="outline" onClick={()=>void load()} disabled={loading}><RefreshCw className="h-4 w-4"/>Refresh</Button><Button asChild><Link to="/leaderboards/new"><Plus className="h-4 w-4"/>Create bot</Link></Button></>}/><Card title="Live leaderboard"><div className="overflow-x-auto"><table className="w-full text-sm"><thead><tr className="border-b border-border text-left text-xs text-muted-foreground"><th className="py-2">Rank</th><th>User</th><th>Points</th></tr></thead><tbody>{live.map((r:any)=><tr key={r.user_id} className="border-b border-border/70"><td className="py-2">{r.rank}</td><td>{r.username??r.full_name??r.user_id}</td><td>{Number(r.points??0).toLocaleString()}</td></tr>)}</tbody></table>{!live.length&&<Empty>No leaderboard data.</Empty>}</div></Card><Card title={`Leaderboard bots (${rows.length})`}><div className="grid gap-2 md:grid-cols-2 xl:grid-cols-3">{rows.map(r=><div key={r.id} className="rounded-md border border-border p-3"><div className="flex items-center justify-between"><div><div className="font-medium">{r.username}</div><div className="text-xs text-muted-foreground">{r.full_name??'—'} · {Number(r.points??0).toLocaleString()} pts</div></div><StatusBadge status={r.is_active?'active':'inactive'} dense/></div><div className="mt-2 flex justify-end gap-1"><Button asChild size="sm" variant="ghost"><Link to={`/leaderboards/${r.id}/edit`}>Edit</Link></Button><Button size="sm" variant="ghost" onClick={()=>void remove(r.id)}><Trash2 className="h-3.5 w-3.5"/></Button></div></div>)}{!rows.length&&<Empty>{loading?'Loading…':'No bots yet.'}</Empty>}</div></Card></div>
}
export function LeaderboardBotEditor(){
 const {id}=useParams();const nav=useNavigate();const editing=!!id;const [f,setF]=useState<any>({username:'',full_name:'',avatar_id:'',points:0,is_active:true,date_of_birth:'',country:'',city:'',address:'',facebook:'',telegram:'',whatsapp:'',bio:'',phone:'',status:'active'});const set=(k:string,v:any)=>setF((x:any)=>({...x,[k]:v}))
 useEffect(()=>{if(editing)void supabase.from('leaderboard_bots').select('*').eq('id',id).single().then(({data,error})=>{if(error)toast.error(errorText(error));else setF(data)})},[id,editing])
 async function submit(e:any){e.preventDefault();try{if(!f.username.trim())throw new Error('Username is required.');const payload={username:f.username.trim(),full_name:f.full_name||null,avatar_id:f.avatar_id||null,points:Number(f.points)||0,is_active:!!f.is_active,date_of_birth:f.date_of_birth||null,country:f.country||null,city:f.city||null,address:f.address||null,facebook:f.facebook||null,telegram:f.telegram||null,whatsapp:f.whatsapp||null,bio:f.bio||null,phone:f.phone||null,status:f.status||'active'};const q=editing?supabase.from('leaderboard_bots').update(payload).eq('id',id):supabase.from('leaderboard_bots').insert(payload);const {error}=await q;if(error)throw error;toast.success(editing?'Bot updated':'Bot created');nav('/leaderboards')}catch(e){toast.error(errorText(e))}}
 return <div className="flex flex-col gap-density-lg"><Back to="/leaderboards" title={editing?'Edit Leaderboard Bot':'Create Leaderboard Bot'}/><form onSubmit={submit} className="flex flex-col gap-density-lg"><Card title="Profile"><div className="grid gap-density-md md:grid-cols-2 xl:grid-cols-3"><Text label="Username" value={f.username} onChange={v=>set('username',v)} required/><Text label="Full name" value={f.full_name} onChange={v=>set('full_name',v)}/><Text label="Points" value={f.points} onChange={v=>set('points',v)} type="number"/><Text label="Avatar ID" value={f.avatar_id} onChange={v=>set('avatar_id',v)}/><Text label="Date of birth" value={f.date_of_birth} onChange={v=>set('date_of_birth',v)} type="date"/><Text label="Country" value={f.country} onChange={v=>set('country',v)}/><Text label="City" value={f.city} onChange={v=>set('city',v)}/><Text label="Phone" value={f.phone} onChange={v=>set('phone',v)}/><Select label="Status" value={f.status||'active'} onChange={v=>set('status',v)} options={['active','inactive'].map(v=>({value:v,label:v}))}/><Toggle label="Active" checked={!!f.is_active} onChange={v=>set('is_active',v)}/></div></Card><Card title="Profile details"><div className="grid gap-density-md md:grid-cols-2"><Text label="Address" value={f.address} onChange={v=>set('address',v)}/><Text label="Facebook" value={f.facebook} onChange={v=>set('facebook',v)}/><Text label="Telegram" value={f.telegram} onChange={v=>set('telegram',v)}/><Text label="WhatsApp" value={f.whatsapp} onChange={v=>set('whatsapp',v)}/><Area label="Bio" value={f.bio} onChange={v=>set('bio',v)}/></div></Card><Actions to="/leaderboards"/></form></div>
}
